const df = $input.first().json;

function bytesToGB(bytes) {
  return (bytes / 1073741824).toFixed(2);
}

function bytesToMB(bytes) {
  return Math.round(bytes / 1048576);
}

// Images
const images = df.Images || [];
const totalImageSize = images.reduce((sum, i) => sum + (i.Size || 0), 0);
const imageCount = images.length;

// Containers
const containers = df.Containers || [];
const runningContainers = containers.filter(c => c.State === 'running').length;
const totalContainerSize = containers.reduce((sum, c) => sum + (c.SizeRootFs || 0), 0);

// Volumes
const volumes = df.Volumes || [];
const totalVolumeSize = volumes.reduce((sum, v) => sum + (v.UsageData ? v.UsageData.Size : 0), 0);

// Build cache
const cache = df.BuildCache || [];
const totalCacheSize = cache.reduce((sum, c) => sum + (c.Size || 0), 0);

const totalGB = parseFloat(bytesToGB(totalImageSize + totalVolumeSize + totalCacheSize));

// Alert thresholds (adjust as needed for your VPS)
const imageAlertGB = 10;   // alert if images > 10 GB
const volumeAlertGB = 15;  // alert if volumes > 15 GB
const totalAlertGB = 25;   // alert if total > 25 GB

const imageSizeGB = parseFloat(bytesToGB(totalImageSize));
const volumeSizeGB = parseFloat(bytesToGB(totalVolumeSize));
const cacheSizeMB = bytesToMB(totalCacheSize);

const alerts = [];
if (imageSizeGB > imageAlertGB) alerts.push(`Images ${imageSizeGB}GB > ${imageAlertGB}GB threshold`);
if (volumeSizeGB > volumeAlertGB) alerts.push(`Volumes ${volumeSizeGB}GB > ${volumeAlertGB}GB threshold`);
if (totalGB > totalAlertGB) alerts.push(`Total ${totalGB}GB > ${totalAlertGB}GB threshold`);

const hasAlerts = alerts.length > 0;

const geminiPrompt = `Docker storage analysis for a self-hosted VPS:\n- Images: ${imageSizeGB} GB (${imageCount} images)\n- Container layers: ${bytesToMB(totalContainerSize)} MB\n- Named volumes: ${volumeSizeGB} GB\n- Build cache: ${cacheSizeMB} MB\n- Total tracked: ${totalGB} GB\n\nAlerts triggered: ${alerts.join('; ') || 'none'}\n\nProvide 2-3 specific, actionable cleanup suggestions if storage is high (e.g., prune old images, identify large volumes). If normal, say all good in one sentence. Plain text, no headers.`;

return [{ json: {
  imageSizeGB, volumeSizeGB, cacheSizeMB, totalGB, imageCount,
  runningContainers, alerts, hasAlerts, geminiPrompt
} }];

const gemRes = $input.first().json;
const prev = $('Parse Storage Stats').first().json;

let advice = '';
try {
  advice = gemRes.candidates[0].content.parts[0].text.trim();
} catch(e) {}

const date = new Date().toISOString().split('T')[0];

let msg = `\u26a0\ufe0f CRYPTEX Storage Alert — ${date}\n\n`;
msg += `\ud83d\udcbe Docker Storage Usage:\n`;
msg += `\u2022 Images: ${prev.imageSizeGB} GB (${prev.imageCount} images)\n`;
msg += `\u2022 Volumes: ${prev.volumeSizeGB} GB\n`;
msg += `\u2022 Build cache: ${prev.cacheSizeMB} MB\n`;
msg += `\u2022 Total: ${prev.totalGB} GB\n\n`;

if (prev.alerts.length > 0) {
  msg += `\u274c Alerts:\n${prev.alerts.map(a => '  • ' + a).join('\n')}\n\n`;
}

if (advice) {
  msg += `\ud83e\udd16 Gemini Advice:\n${advice}\n\n`;
}

msg += `Cleanup commands (run in workstation):\ndocker image prune -a --filter until=168h\ndocker system prune --volumes`;

return [{ json: { message: msg } }];
